def hydrate_time(nanoseconds, tz=None):
    if not isinstance(nanoseconds, int) or nanoseconds < 0:
        raise ValueError("nanoseconds must be a non-negative integer")
    if tz is not None and not hasattr(tz, 'utcoffset'):
        raise ValueError("tz must be a timezone-aware object with utcoffset method")
    total_hours, remainder = divmod(nanoseconds, 3600 * 10**9)
    total_minutes, remainder = divmod(remainder, 60 * 10**9)
    total_seconds, nanos = divmod(remainder, 10**9)
    if total_hours > 23 or total_minutes > 59 or total_seconds > 59:
        raise ValueError("nanoseconds value exceeds valid time range")
    if tz is not None:
        return datetime(timezone=tz).time(hour=int(total_hours), minute=int(total_minutes), second=int(total_seconds), microsecond=int(nanos // 1000))
    else:
        return datetime().time(hour=int(total_hours), minute=int(total_minutes), second=int(total_seconds), microsecond=int(nanos // 1000))

