def protocol_handlers(cls, protocol_version=None):
        handlers = {}
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol version must be passed as a tuple")
            if len(protocol_version) != 2:
                raise TypeError("protocol version tuple must have exactly two elements")
            if not all(isinstance(v, int) and v >= 0 for v in protocol_version):
                raise TypeError("protocol version elements must be non-negative integers")
        available_handlers = getattr(cls, "_protocol_handlers", {})
        if protocol_version is None:
            handlers.update(available_handlers)
        else:
            if protocol_version in available_handlers:
                handlers[protocol_version] = available_handlers[protocol_version]
        return handlers

