def data(self, *keys):
    # Build a dictionary of field names to values from the record
    items = self._items
    record_data = {item[0]: item[1] for item in items}

    # If no keys are specified, return all values
    if not keys:
        return record_data

    # If keys are specified, extract only those
    result = {}
    for key in keys:
        if isinstance(key, int):
            # Handle integer index
            if key < 0:
                # Negative indexing: count from the end
                idx = key + len(items)
                if idx < 0 or idx >= len(items):
                    raise IndexError(f"Index {key} is out of bounds")
                key = items[idx][0]
            else:
                if key >= len(items):
                    raise IndexError(f"Index {key} is out of bounds")
                key = items[key][0]
        # Now key is a field name
        if key in record_data:
            result[key] = record_data[key]
        else:
            result[key] = None

    return result

