def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class_dict = {'srid_map': srid_map}
    for field in fields:
        if field in srid_map:
            class_dict[field] = property(lambda self, _f=field: self.attrs.get(_f) if self.attrs else None)
        else:
            class_dict[field] = property(lambda self, _f=field: self.attrs.get(_f) if self.attrs else None)

    def __init__(self, *args, **kwargs):
        self.attrs = {}
        if args:
            args = list(args)
            for i, field in enumerate(fields):
                if i < len(args):
                    self.attrs[field] = args[i]
        for key, value in kwargs.items():
            if key in fields:
                self.attrs[key] = value

    coordinates = tuple(fields.index(f) for f in fields if f not in srid_map)

    class_dict['points'] = coordinates

    attrs = {'__init__': __init__}
    for field in fields:
        if field in srid_map:
            attrs[field] = property(lambda self, _f=field: self.attrs[_f])
        else:
            attrs[field] = property(lambda self, _f=field: self.attrs[_f])

    cls = type(name, (), attrs)
    return cls

