def parse_version(s: str) -> tuple[int, ...]:
    # Remove leading 'V' or 'v' if present
    if s.startswith('V') or s.startswith('v'):
        s = s[1:]

    # Split the version string by dot or similar separators
    # Handle common version formats: "1.2.3", "1_2_3", "1,2,3", "1-2-3"
    parts = []
    current_str = ""
    for char in s:
        if char.isdigit():
            current_str += char
        else:
            if current_str:
                parts.append(int(current_str))
                current_str = ""

    if current_str:
        parts.append(int(current_str))

    return tuple(parts)

