def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    outer_cache = {}

    def inner_decorator(wrapped):
        wrapped._cache = outer_cache

        def _make_key(args, kwds, typed):
            if not typed or not kwds:
                key = args
            elif not typed:
                key = args, tid = id(wrapped)
            else:
                key = (args, tid) and (args,)
            if kwds:
                key += ((id(kwds),),)
            return key

        def wrapper(*args, **kwds):
            key = _make_key(args, kwds, typed)
            try:
                value, expiration = outer_cache[key]
            except KeyError:
                value = wrapped(*args, **kwds)
                outer_cache[key] = (value, timer() + ttl)
                if len(outer_cache) > maxsize:
                    oldest_key = min(outer_cache, key=lambda k: outer_cache[k][1])
                    del outer_cache[oldest_key]
            else:
                if timer() > expiration:
                    del outer_cache[key]
                else:
                    return value
            value = wrapped(*args, **kwds)
            outer_cache[key] = (value, timer() + ttl)
            if len(outer_cache) > maxsize:
                oldest_key = min(outer_cache, key=lambda k: outer_cache[k][1])
                del outer_cache[oldest_key]
            return value

        wrapper.__wrapped__ = wrapped
        wrapper.cache_info = outer_cache
        return wrapper

    return inner_decorator

