def lru_cache(maxsize=128, typed=False):
    from threading import Lock
    from collections import OrderedDict
    import functools

    maxsize = None if maxsize == -1 else maxsize

    def wrapper(func):
        nonlocal maxsize
        if maxsize is not None:
            key = lambda *args, **kwds: (args, frozenset(sorted(kwds.items())) if kwds else None)
            if typed:
                key = lambda *args, **kwds: (args, frozenset(sorted(kwds.items())) if kwds else None,
                                             tuple(type(a) for a in args))
            else:
                key = lambda *args, **kwds: (args, frozenset(sorted(kwds.items())) if kwds else None)
        else:
            key = lambda *args, **kwds: (args, frozenset(sorted(kwds.items())) if kwds else None)

        cache = OrderedDict()
        hits = misses = 0
        lock = Lock()

        @functools.wraps(func)
        def wrapper(*args, **kwds):
            nonlocal hits, misses
            if maxsize is None:
                k = key(*args, **kwds)
                with lock:
                    try:
                        result = cache[k]
                    except KeyError:
                        result = func(*args, **kwds)
                        cache[k] = result
                    else:
                        hits += 1
                        cache.move_to_end(k)
                    return result
            else:
                k = key(*args, **kwds)
                with lock:
