def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    if extract_spec_version:
        inventory_type = inventory.get('type')
        if not inventory_type:
            # Fall back to self.spec_version
            pass
        else:
            try:
                # Determine spec version from type value
                if isinstance(inventory_type, str):
                    version_str = inventory_type
                    if version_str.startswith('spec'):
                        # Try to extract version number
                        parts = version_str.split()
                        if len(parts) >= 2:
                            version_parts = parts[1].split('.')
                            if len(version_parts) >= 2:
                                major = int(version_parts[0])
                                minor = int(version_parts[1])
                                self.spec_version = (major, minor)
                            else:
                                major = int(version_parts[0])
                                self.spec_version = (major, 0)
                        else:
                            # Use default or existing spec_version
                            pass
                    else:
                        # Unknown type, use existing spec_version
                        pass
                else:
                    # Invalid type value, use existing spec_version
                    pass
            except (ValueError, IndexError):
                # Invalid version format, use existing spec_version
                pass

    # Basic validation of inventory structure
    if 'entities' not in inventory:
        raise ValueError("Inventory must contain an 'entities' key")

    if not isinstance(inventory['entities'], dict):
        raise ValueError("The 'entities' key must be a dictionary")

    errors = []

    for entity_name, entity in inventory['entities'].items():
        if not isinstance(entity_name, str) or not entity_name:
            errors.append("Entity names must be non-empty strings")

        if not isinstance(entity, dict):
            errors.append(f"Entity '{entity_name}' must be a dictionary")
            continue

        if '__actions__' not in entity:
            entity['__actions__'] = []

        if not isinstance(entity['__actions__'], list):
            errors.append(f"Entity '{entity_name}' must have a list of actions")

        props = entity.get('properties', {})
        if not isinstance(props, dict):
            errors.append(f"Entity '{entity_name}' properties must be a dictionary")

    if errors:
        raise ValueError(f"Inventory validation failed: {errors}")

    return True

