def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Initialize set of all digests found in manifest files
        all_digests = set()

        # Extract all digests from manifest files
        for manifest_file in manifest_files:
            for digest in manifest_file.get('digests', []):
                all_digests.add(digest)

        # Check for missing digests (used but not present in manifest)
        missing_digests = digests_used - all_digests

        # Check for unused digests (present in manifest but not used)
        unused_digests = all_digests - digests_used

        # If there are missing or unused digests, raise an error or warning
        if missing_digests:
            raise ValueError(f"Missing digests in manifest: {missing_digests}")

        if unused_digests:
            # Unused digests might be acceptable in some scenarios
            # For strict checking, this would be an error; otherwise just a note
            return {
                'all_present': True,
                'all_used': False,
                'missing_digests': missing_digests,
                'unused_digests': unused_digests
            }

        return {
            'all_present': True,
            'all_used': True,
            'missing_digests': set(),
            'unused_digests': set()
        }

