def get_logical_path_map(inventory, version):
        """Get a map of logical paths in state to files on disk for version in inventory.

        Returns a dictionary: logical_path_in_state -> set(content_files)

        The set of content_files may includes references to duplicate files in
        later versions than the version being described.
        """
        if not isinstance(inventory, dict) or "versions" not in inventory:
            return {}

        if version is None:
            return {}

        versions = inventory["versions"]
        if version not in versions:
            return {}

        version_data = versions[version]
        if not isinstance(version_data, dict) or "file_map" not in version_data:
            return {}

        file_map = version_data["file_map"]

        result = {}

        # Build reverse mapping: logical path -> set of content files
        for logical_path, file_info in file_map.items():
            if not isinstance(file_info, dict):
                continue

            content_files = file_info.get("content_files", set())
            if isinstance(content_files, list):
                content_files = set(content_files)
            elif isinstance(content_files, str):
                content_files = {content_files}
            elif not isinstance(content_files, (set, list, tuple)):
                continue

            if logical_path in result:
                result[logical_path].update(content_files)
            else:
                result[logical_path] = set(content_files)

        return result

