def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if "files" not in fixity:
        raise ValueError("Fixity block must contain a 'files' key")

    files = fixity["files"]
    if not isinstance(files, dict):
        raise ValueError("The 'files' entry in fixity must be a dictionary")

    for filename, checksum in files.items():
        # Ensure checksum is a dictionary with 'value' and 'algorithm' keys
        if not isinstance(checksum, dict):
            raise ValueError("Each file entry in fixity must be a dictionary with 'value' and 'algorithm'")
        if "value" not in checksum or "algorithm" not in checksum:
            raise ValueError("Each file entry in fixity must contain 'value' and 'algorithm' keys")
        if not isinstance(checksum["value"], str) or not checksum["value"]:
            raise ValueError("Checksum value must be a non-empty string")
        if not isinstance(checksum["algorithm"], str) or not checksum["algorithm"]:
            raise ValueError("Checksum algorithm must be a non-empty string")

        # Check that the file is listed in the manifest
        if filename not in manifest_files:
            raise ValueError(f"File '{filename}' referenced in fixity is not in the manifest")

    return True

