def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        # Assuming self is a dictionary or has a similar structure
        if not isinstance(self, dict):
            raise TypeError("`pretty` method is only implemented for dictionary-like objects.")

        if debug:
            return self.__repr__()

        lines = []
        keys = sorted(self.keys()) if self else []
        for key in keys:
            value = self[key]
            if isinstance(value, (list, tuple)):
                # Format list/tuple elements
                if len(value) == 0:
                    val_str = "[]" if isinstance(value, list) else "()"
                else:
                    items = [self._format_item(item, indent + 1) for item in value]
                    if isinstance(value, tuple):
                        val_str = "(\n" + ",\n".join([" " * indent * 2 + f"{item}" for item in items]) + "\n" + " " * indent + ")"
                    else:
                        val_str = "[\n" + ",\n".join([" " * indent * 2 + f"{item}" for item in items]) + "\n" + " " * indent + "]"
            elif isinstance(value, dict):
                # Recursively format nested dicts
                nested_pretty = value.pretty(indent + 1, debug=debug)
                val_str = "{\n" + ",\n".join([" " * indent * 2 + line for line in nested_pretty.split("\n")]) + "\n" + " " * indent + "}"
            else:
                val_str = repr(value)
            lines.append(f"{' ' * indent}{repr(key)}: {val_str}")

        if self:
            return "{\n" + ",\n".join(lines) + "\n" + "}"
        else:
            return "{}"

    def _format_item(self, item, indent):
        """Helper method to format an item with the given indent."""
        if isinstance(item, (list, tuple)):
            if len(item) == 0:
                return "[]" if isinstance(item, list) else "()"
            else:
                items = [self._format_item(subitem, indent + 1) for subitem in item]
                prefix = "(\n" if isinstance(item, tuple) else "[\n"
                suffix = "\n" + " " * indent + ")" if isinstance(item, tuple) else "\n" + " " * indent + "]"
                return prefix + ",\n".join([" " * indent * 2 + f"{subitem}" for subitem in items]) + suffix
        elif isinstance(item, dict):
            nested_pretty = item.pretty(indent, debug=False)
            return "{\n" + ",\n".join([" " * indent * 2 + line for line in nested_pretty.split("\n")]) + "\n" + " " * indent + "}"
        else:
            return repr(item)

