def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    # Obtain the root
    try:
        root_entry = self.entries[""]
    except KeyError:
        raise ValueError("Root entry not found")

    # Recursively validate the hierarchy
    def _validate(entry, is_root=False):
        nonlocal num_objects, good_objects

        num_objects += 1
        is_valid = True

        # Validate the entry itself
        if validate_objects:
            try:
                entry.validate(check_digests=check_digests)
            except Exception as e:
                is_valid = False
                if show_warnings:
                    print(f"Warning: Entry {entry.type.typeval} at {entry.item} failed validation: {e}")

        if is_valid:
            good_objects += 1

        # For directories (root or non-blob), validate children
        if not is_root and entry.type.typeval == "blob":
            return

        # If it's a directory (including root), validate all children
        if "children" in entry:
            for child_entry in entry["children"].values():
                _validate(child_entry, is_root=False)
        elif is_root:
            # Root might store direct children differently
            if "children" in entry.root:
                for child_entry in entry.root["children"].values():
                    _validate(child_entry, is_root=False)

    _validate(root_entry, is_root=True)

    return num_objects, good_objects

