def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        return False

    host = host.lower().strip()

    # Check for common localhost names
    if host in ('localhost', 'localhost.localdomain'):
        return True

    # Check for IP addresses
    if '.' in host:
        # IPv4 loopback addresses
        if host == '127.0.0.1' or host.startswith('127.'):
            return True
        # IPv4 mapped IPv6 loopback
        if host == '::1' or host == '0:0:0:0:0:ffff:127.0.0.1':
            return True

    # Check for IPv6 loopback
    if host == '::1':
        return True

    # Try to resolve the host and check if it resolves to loopback addresses
    try:
        import socket
        addr_info = socket.getaddrinfo(host, None)
        for addr in addr_info:
            ip = addr[4][0]
            if ip == '127.0.0.1' or ip == '::1':
                return True
            # Also check for any 127.x.x.x addresses
            if ip.startswith('127.'):
                return True
    except Exception:
        pass

    return False

