def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:

    """
    from urllib.parse import urlparse
    if not isinstance(image_href, str) or not image_href:
        raise ValueError("Image href must be a non-empty string")

    try:
        url = urlparse(image_href)
    except Exception as e:
        raise ValueError(f"Invalid image href: {e}")

    netloc = url.netloc or ""
    use_ssl = url.scheme == "https"

    # Extract image_id from path
    path = url.path
    if path:
        # Take the last part of the path as the image_id
        image_id = path.rstrip('/').split('/')[-1]
    else:
        image_id = ""

    return (image_id, netloc, use_ssl)

