    """Call the given command(s)."""
    try:
        process = subprocess.Popen(
            commands + args,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if hide_stderr else None,
            env=env
        )
        output, stderr = process.communicate()
        if process.returncode != 0:
            return_value = (process.returncode, output, stderr)
            if verbose:
                print(f"Command {' '.join(commands + args)} failed with return code {process.returncode}")
                if stderr:
                    print(f"stderr: {stderr.decode('utf-8')}")
            return return_value
        output = output.decode('utf-8').strip()
        return (0, output, stderr.decode('utf-8').strip() if stderr else '')
    except FileNotFoundError:
        return (1, '', f"Command not found: {commands[0]}")
    except Exception as e:
        return (1, '', str(e))

