def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json

    import os

    import re

    import logging
    config_dict = {}
    errors = []
    if overrides is None:
        overrides = {}
    for filename in config_filenames:
        try:
            config_dict[filename] = {}
            # Read the file
            with open(filename, 'r') as f:
                content = f.read()
            # Resolve environment variables in the content
            if resolve_env:
                # Replace environment variables in the form of ${VAR_NAME}
                def replace_env(match):
                    var_name = match.group(1)
                    value = os.environ.get(var_name, '')
                    return value
                content = re.sub(r'\$\{([^}]+)\}', replace_env, content)
            # Parse as JSON
            try:
                parsed_config = json.loads(content)
            except json.JSONDecodeError as e:
                error_record = logging.LogRecord(name='', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Invalid JSON in {filename}: {str(e)}", args=None, exc_info=None)
                errors.append(error_record)
                continue
            if not isinstance(parsed_config, dict):
                error_record = logging.LogRecord(name='', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Invalid configuration format in {filename}", args=None, exc_info=None)
                errors.append(error_record)
                del config_dict[filename]
                continue
            # Apply overrides
            for key, value in overrides.items():
                if key in parsed_config:
                    parsed_config[key] = value
            config_dict[filename] = parsed_config
        except FileNotFoundError:
            error_record = logging.LogRecord(name='', level=logging.ERROR, pathname=filename, lineno=0, msg=f"File not found: {filename}", args=None, exc_info=None)
            errors.append(error_record)
            del config_dict[filename]
        except Exception as e:
            error_record = logging.LogRecord(name='', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Error processing {filename}: {str(e)}", args=None, exc_info=None)
            errors.append(error_record)
            if filename in config_dict:
