    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if request is None:
        return None

    # Check if it's a public message (typically has 'object' key with 'type' == 'status')
    if isinstance(request, dict) and 'object' in request:
        obj = request['object']
        if isinstance(obj, dict) and obj.get('type') == 'status':
            return 'public'

    # Check if it's a private message (typically has 'conversation' key)
    if isinstance(request, dict) and 'conversation' in request:
        conv = request['conversation']
        if isinstance(conv, dict):
            return 'private'

    # Check for legacy payload format (e.g., top-level 'type' field)
    if isinstance(request, dict):
        if 'type' in request:
            req_type = request['type']
            if req_type == 'status':
                return 'public_legacy'
            elif req_type == 'conversation':
                return 'private_legacy'

    # Not a recognized Diaspora request
