def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """

    # Try to parse as JSON first (new format)
    try:
        data = json.loads(document)
        # Verify it looks like a valid webfinger JSON response
        if "subject" not in data or "links" not in data:
            raise ValueError("Invalid webfinger JSON format")
        return data
    except (json.JSONDecodeError, ValueError):
        pass

    # Fall back to XRD parsing (old format)
    try:
        from xml.etree import ElementTree as ET

        root = ET.fromstring(document)

        result = {'subject': None, 'links': []}

        # Find subject in XRD
        for subject in root.findall('.//{urn:xmpp:wdg}subject'):
            result['subject'] = subject.text
            break
        # Alternative namespace or direct child
        if result['subject'] is None:
            for subject in root.findall('./subject'):
                result['subject'] = subject.text
                break

        # Find all alias and link tags
        for alias in root.findall('.//{urn:xmpp:wdg}alias'):
            if alias.text:
                if not any(link.get('rel') == 'http://tools.ietf.org/html/rfc5523' and link.get('href') == alias.text for link in result['links']):
                    result['links'].append({
                        'rel': 'http://tools.ietf.org/html/rfc5523',
                        'href': alias.text
                    })

        for link in root.findall('.//{urn:xmpp:wdg}link'):
            rel = link.get('rel')
            href = link.get('href')
            if rel and href:
                result['links'].append({
                    'rel': rel,
                    'href': href
                })

        # Alternative: some XRD files might have <xr:subject> and <xr:alias> and <xr:link>
        if result['subject'] is None:
            for subject in root.findall('./xr:subject', namespaces={'xr': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}):
                result['subject'] = subject.text
                break

        if not result['links']:
            for alias in root.findall('./xr:alias', namespaces={'xr': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}):
                if alias.text:
                    result['links'].append({
                        'rel': 'http://tools.ietf.org/html/rfc5523',
                        'href': alias.text
                    })

            for link in root.findall('./xr:link', namespaces={'xr': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}):
                rel = link.get('rel')
                href = link.get('href')
                if rel and href:
                    result['links'].append({
                        'rel': rel,
                        'href': href
                    })

        if result['subject'] is None:
            raise ValueError("No subject found in webfinger XRD document")

        return result
    except ET.ParseError:
        raise ValueError("Invalid webfinger document: neither valid JSON nor XRD XML")
    except Exception as e:
        raise ValueError(f"Failed to parse webfinger document: {str(e)}")

