def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Check if the plugin directory exists
    if not os.path.exists(plugin_dir) or not os.path.isdir(plugin_dir):
        raise ValueError(f"Invalid plugin directory: {plugin_dir}")

    # Look for a plugin spec file (e.g., plugin.json) in the plugin directory
    spec_file = os.path.join(plugin_dir, "plugin.json")
    if not os.path.exists(spec_file):
        raise FileNotFoundError(f"Plugin spec file not found in directory: {plugin_dir}")

    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            spec = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON in plugin spec file: {e}")
    except Exception as e:
        raise IOError(f"Error reading plugin spec file: {e}")

    # Flatten the dictionary: convert nested keys into a flat dict with dotted keys
    def flatten_dict(d, parent_key='', sep='.'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(spec)

